// 1. Declare an undefined class template.
template<typename T>
class TD; // TD stands for Type Displayer

const int theAnswer = 42;
auto x = theAnswer;
auto y = &theAnswer;

// 2. Attempt to instantiate it to cause an error.
// The compiler error for this line will reveal x's type.
// E.g., "error: aggregate 'TD<int> xType' has incomplete type"
TD<decltype(x)> xType;

// The error for this line will reveal y's type.
// E.g., "error: aggregate 'TD<const int*> yType' has incomplete type"
TD<decltype(y)> yType;
